const KEY_PATTERN = /^rb_live_([0-9a-f]{8})_([A-Za-z0-9_-]{43})$/;

export interface ApiKey {
  id: number;
  name: string;
  buildingId: number;
  scopes: string[];
}

export function newApiKey(): { key: string; prefix: string } {
  const prefix = randomBytes(4).toString("hex");
  const secret = randomBytes(32).toString("base64url");
  return { key: `rb_live_${prefix}_${secret}`, prefix };
}

export function createApiKeyRepository(db: Queryable) {
  return {
    async create(name: string, buildingId: number, scopes: string[]) {
      const { key, prefix } = newApiKey();
      const { rows } = await db.query<{ id: number }>(
        `INSERT INTO api_keys (prefix, key_hash, name, building_id, scopes)
          VALUES ($1, $2, $3, $4, $5) RETURNING id`,
        [prefix, sha256(key), name, buildingId, scopes],
      );
      return { id: rows[0]!.id, key, prefix };
    },

    async check(presented: string): Promise<ApiKey | null> {
      const match = KEY_PATTERN.exec(presented);
      if (!match) return null;
      const { rows } = await db.query(
        `SELECT id, name, building_id AS "buildingId", scopes, key_hash AS "keyHash"
          FROM api_keys WHERE prefix = $1 AND revoked_at IS NULL`,
        [match[1]],
      );
      const row = rows[0];
      if (!row) return null;
      const presentedHash = Buffer.from(sha256(presented), "hex");
      if (!timingSafeEqual(presentedHash, Buffer.from(row.keyHash, "hex"))) return null;
      await db.query(
        `UPDATE api_keys SET last_used_at = now()
          WHERE id = $1 AND (last_used_at IS NULL OR last_used_at < now() - interval '1 minute')`,
        [row.id],
      );
      return { id: row.id, name: row.name, buildingId: row.buildingId, scopes: row.scopes };
    },
  };
}

interface SsoConfig {
  issuer: string;
  clientId: string;
  clientSecret: string;
  redirectUri: string;
  appUrl: string;
}

export async function ssoRoutes(cfg: SsoConfig, identities: IdentityLinker): Promise<Router> {
  const provider = await oidc.discovery(new URL(cfg.issuer), cfg.clientId, cfg.clientSecret);
  const router = Router();

  router.get("/start", async (req, res) => {
    const sso = {
      state: oidc.randomState(),
      nonce: oidc.randomNonce(),
      verifier: oidc.randomPKCECodeVerifier(),
    };
    req.session.sso = sso;
    const url = oidc.buildAuthorizationUrl(provider, {
      redirect_uri: cfg.redirectUri,
      scope: "openid email profile",
      state: sso.state,
      nonce: sso.nonce,
      code_challenge: await oidc.calculatePKCECodeChallenge(sso.verifier),
      code_challenge_method: "S256",
    });
    res.redirect(url.href);
  });

  router.get("/callback", async (req, res) => {
    const sso = req.session.sso;
    if (!sso) throw new UnauthorizedError("Start the sign-in again.");
    const tokens = await oidc.authorizationCodeGrant(
      provider,
      new URL(req.originalUrl, cfg.redirectUri),
      {
        expectedState: sso.state,
        expectedNonce: sso.nonce,
        pkceCodeVerifier: sso.verifier,
        idTokenExpected: true,
      },
    );
    const claims = tokens.claims()!;
    const user = await identities.link(claims.iss, claims.sub, claims);
    await startSession(req, user.id);
    res.redirect(cfg.appUrl);
  });

  return router;
}

export function createIdentityLinker(db: Queryable) {
  return {
    async link(issuer: string, subject: string, claims: IDToken): Promise<{ id: number }> {
      const linked = await db.query<{ id: number }>(
        `SELECT user_id AS id FROM oidc_identities WHERE issuer = $1 AND subject = $2`,
        [issuer, subject],
      );
      if (linked.rows[0]) return linked.rows[0];

      if (claims.email_verified !== true || typeof claims.email !== "string") {
        throw new ForbiddenError("Your university account has no verified email.");
      }
      const staff = await db.query<{ id: number }>(
        `SELECT id FROM users WHERE lower(email) = lower($1) AND role IN ('staff', 'admin')`,
        [claims.email],
      );
      const user = staff.rows[0];
      if (!user) throw new ForbiddenError("Ask an admin to add you as staff first.");
      await db.query(`INSERT INTO oidc_identities (issuer, subject, user_id) VALUES ($1, $2, $3)`, [
        issuer,
        subject,
        user.id,
      ]);
      return user;
    },
  };
}

export type IdentityLinker = ReturnType<typeof createIdentityLinker>;

import { createRemoteJWKSet, jwtVerify } from "jose";

const UNIVERSITY = "https://login.university.example";
const jwks = createRemoteJWKSet(new URL(`${UNIVERSITY}/.well-known/jwks.json`));

export async function verifyUniversityToken(token: string) {
  const { payload } = await jwtVerify(token, jwks, {
    issuer: UNIVERSITY,
    audience: "https://api.roombook.example",
    algorithms: ["RS256", "ES256"],
    requiredClaims: ["sub", "exp"],
  });
  return { subject: payload.sub!, scopes: String(payload.scope ?? "").split(" ") };
}

export type Role = "member" | "staff" | "admin";

export interface Principal {
  via: "session" | "bearer" | "api-key";
  userId: number | null;
  role: Role | null;
  buildingId: number | null;
  scopes: ReadonlySet<string>;
}

const MEMBER = ["bookings:read", "bookings:write", "feedback:write"];
const STAFF = [...MEMBER, "rooms:write", "schedule:read", "api-keys:write"];

export const ROLE_SCOPES: Record<Role, readonly string[]> = {
  member: MEMBER,
  staff: STAFF,
  admin: [...STAFF, "rooms:delete", "webhooks:write"],
};

export function userPrincipal(
  via: "session" | "bearer",
  user: { id: number; role: Role; buildingId: number | null },
  granted?: readonly string[],
): Principal {
  const allowed = ROLE_SCOPES[user.role];
  const scopes = granted ? allowed.filter((s) => granted.includes(s)) : allowed;
  return {
    via,
    userId: user.id,
    role: user.role,
    buildingId: user.buildingId,
    scopes: new Set(scopes),
  };
}

export function authenticate({ users, tokens, apiKeys }: Deps): RequestHandler {
  return async (req, res, next) => {
    const authorization = req.get("authorization");
    const apiKey = req.get("api-key");

    if (req.session.userId !== undefined) {
      const user = await users.findById(req.session.userId);
      if (!user) throw new UnauthorizedError();
      res.locals.principal = userPrincipal("session", user);
    } else if (authorization?.startsWith("Bearer ")) {
      const claims = await tokens.verify(authorization.slice(7)).catch(() => {
        throw new UnauthorizedError("The access token is invalid or expired.");
      });
      res.locals.principal = userPrincipal("bearer", claims, claims.scopes);
    } else if (apiKey) {
      const key = await apiKeys.check(apiKey);
      if (!key) throw new UnauthorizedError("The API key is invalid or revoked.");
      res.locals.principal = {
        via: "api-key",
        userId: null,
        role: null,
        buildingId: key.buildingId,
        scopes: new Set(key.scopes),
      };
    }
    next();
  };
}

